package com.ailab.system.report.provider;
import com.ailab.system.report.config.*; import com.ailab.system.report.model.*; import java.util.*; import org.springframework.stereotype.Component;
@Component public final class TaskDetailProvider extends AbstractLabDataSourceProvider { public TaskDetailProvider(){super(ReportConfigCatalog.TASK_DETAIL, fields());} protected ReportSectionData loadValidated(ReportQueryCriteria c,ReportSectionConfig s){List<Map<String,Object>> r=copyRows(mapper().selectTasks(c));return section(c,s,r,summaryCount(r));} static Set<String> fields(){return new LinkedHashSet<String>(Arrays.asList("period","bizLine","owner","ownerId","memberId","status","resultStatus","taskLevel","planDate","title","deliverable","nextAction","coordination","block"));}}
